The base-change map induces an isomorphism
    \[
    \bigl\{\pi \in \mathrm{Temp}_H(G) \mapsto I_\pi(f),\ f\in C_c^\infty(G)\bigr\}
    \;\cong\; 
    \mathfrak{Z}_{\mathrm{gen}}(U(n)).
    \]
    Equivalently,
    \[
    \bigl\{\rho \in \mathrm{Temp_{gen}}(U(n)) \mapsto I_{BC_n(\rho)}(f),\ f\in C_c^\infty(G)\bigr\}
    \;=\;
    \mathfrak{Z}_{\mathrm{gen}}(U(n)).
    \]

\label{Wfpi}
    Let $Q=MU$ be a parabolic subgroup of $G=G_n$ and $\sigma \in \mathrm{Irr} (M)$ be square-integrable, set $\pi=i_Q^G(\sigma)$. For all $f\in C_c^\infty(G)$ we define
    \begin{enumerate}
        \item a function $f_\pi \in C^\infty(G)$, such that for all $g \in G$
        $$f_\pi(g):= \mathrm{Trace}(\pi(g)\pi(f^\vee)).$$
        \item a function $W_f\in C^\infty(N_n\backslash G\times N_n\backslash G, \psi_n^{-1}\otimes \psi_n)$, such that for all $(g_1, g_2)\in G\times G$
        $$W_f(g_1, g_2)= \int_N f(g_1^{-1}ug_2)\psi_n(u)^{-1} du.$$
    \end{enumerate}

\label{Wpi}
    Let $Q=MU$ be a parabolic subgroup of $G_n$, $\sigma\in \mathrm{Irr} (M)$ be supercuspidal, set $\pi = i_Q^{G_n}(\sigma)$. Let $\pi_+$ denote the unique $\psi_n$-generic irreducible subquotient of $\pi$. Then 
    $$W_{f,\pi}^1=W_{f, \pi_+}^1 \in \mathcal{W}(\pi_+, \psi_n).$$

\label{propcuspBC}
    Let $\psi:W_E \to \mathrm{GL}_n(\mathbb{C})$ be a conjugate-orthogonal representation. There exists a unique conjugate-orthogonal Langlands parameter $\varphi \in \Phi(G_n(E))$ verifying the following conditions.
    \begin{enumerate}
        \item $\varphi^{ss}=\psi$, 
        \item $L(s, \varphi, \mathrm{As}^-)$ has no pole at $s=1$.
    \end{enumerate}

Let $\Tilde{\psi}\in \mathrm{Irr}_u(W_E)$ be conjugate-dual and let $E=E_{\Tilde{\psi}} \subset \mathbb{R}$ be the corresponding multiset. Then, there exists a unique partition $S_{\Tilde{\psi}}$ of $E$ into segments such that:
        \begin{enumerate}
            \item $S_{\Tilde{\psi}}=-S_{\Tilde{\psi}}$, 
            \item For all $I\in S_{\Tilde{\psi}}$, if $I=-I$ and $\mathrm{sgn}(\Tilde{\psi})\mathrm{sgn}(I)=-1$, then $I$ appears with even multiplicity in $S_{\Tilde{\psi}}$.
            \item For all $I,J\in S_{\Tilde{\psi}}$, if $I$ and $J$ are linked then $J=-I$, $I$ appears with multiplicity one in $S_{\Tilde{\psi}}$ and $\mathrm{sgn(\Tilde{\psi})}\mathrm{sgn}(I\cup-I)=-1$.           
        \end{enumerate}

\label{CoroGKfam}
    Let $X= \mathbb{C}[\mathcal{X}(L)]$ and $X'= X^{W(L, \rho)}$. There exists a function $f\in C_c^\infty(G)$, such that 
    $$W_{f, \pi_{X'}}^1 \in C_c^\infty(N_n\backslash P_n, X', \psi_n).$$

Let $G=G_n(E)$, $H=G_n(F)$, and $\pi\in \mathrm{Temp}_H(G)$. The linear form $\beta$, defined by 
    $$\beta (W) = \int_{N_n(F)\backslash P_n(F)} W(p)dp, \ \mathrm{for} \ W\in \mathcal{W}(\pi^\vee, \psi_n^{-1}),$$
    is a non trivial element in $ \mathrm{Hom}_H(\mathcal{W}(\pi^\vee, \psi_n^{-1}), \mathbf{1})$ (Section 4 of \cite{Offen}). We then define the \emph{relative character}, $I_\pi$ of $\pi$ by the composition  
    $$\xymatrix{
     C_c^\infty(G)   \ar[rd]_{I_\pi} \ar[r]  & \mathcal{W}(\pi^\vee, \psi_n^{-1}) \otimes \mathcal{W}(\pi, \psi_n)\ar[d]^{\beta \otimes \mathbf{ev}_1} \\
      & \mathbb{C}
     }$$
    Therefore, by identifying again $\overline{\mathcal{W}(\pi, \psi_n)}$ with ${\mathcal{W}(\pi^\vee, \psi_n^{-1})}$ we have 
     $$I_\pi(f) = \sum_{W\in \mathcal{B}(\pi, \psi_n)} \beta(\overline{W}) R(f)W(1) \in \mathbb{C}$$
     where $\mathcal{B}(\pi, \psi_n)$ is a suitable orthonormal basis of $\mathcal{W}(\pi, \psi_n)$.

\label{mainT}
    The base-change map induces an isomorphism
    $$\mathcal{I} \cong \mathfrak{Z}_{\mathrm{gen}}(U(n)).$$

\label{RestReg}
    Let $\Phi : \mathbb{C}^n \to \mathbb{C}$ be a meromorphic function and let $V, \Delta$ be vector subspaces of $\mathbb{C}^n$, with $\dim \Delta = 1$. Suppose the following conditions.
    \begin{enumerate}

        \item The restriction $\Phi\vert_V$ is well defined as a meromorphic function. In other words, $V$ is not included in any of the poles of $\Phi$.
        \item For all $v\in V$, the restriction $\Phi\vert_{v+\Delta}$ is well defined as a meromorphic function and is regular in $v$.
        \item The poles $D_1, \dots, D_m$ of $\Phi$ are all simple and affine hyperplanes, and for all $i\not= j $
        $$D_i \cap V \not = D_j \cap V.$$

    \end{enumerate}

    Then $\Phi\vert_V$ is holomorphic on $V$.

\label{antiinv}
    Let $V$ be a unipotent group (defined over a field of characteristic $0$) and $\iota\in \mathrm{Aut}(V)$ be an involution, then 
    $$V^{\iota = -1} = \{\iota(v)^{-1}v, \ v\in V\}.$$
